-- No provider requests. All synthetic keys, registrations and runtime changes roll back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,pg_catalog;
select no_plan();
select ok(not has_function_privilege('anon','public.configure_customer_push_credential(text,jsonb)','EXECUTE'),'anonymous setter denied');
select ok(not has_function_privilege('authenticated','public.configure_customer_push_credential(text,jsonb)','EXECUTE'),'signed-in setter denied');
select ok(has_function_privilege('service_role','public.configure_customer_push_credential(text,jsonb)','EXECUTE'),'service setter allowed');
select ok(not has_function_privilege('anon','private.configure_customer_push_credential(text,jsonb)','EXECUTE'),'private anonymous setter denied');
select ok(not has_function_privilege('authenticated','private.configure_customer_push_credential(text,jsonb)','EXECUTE'),'private signed-in setter denied');
select ok(not (select prosecdef from pg_proc where oid='public.configure_customer_push_credential(text,jsonb)'::regprocedure),'public wrapper remains invoker');
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='private.configure_customer_push_credential(text,jsonb)'::regprocedure),'private definer has empty search path');
select ok(not has_function_privilege('authenticated','public.customer_push_configuration()','EXECUTE'),'configuration remains private');
select public.configure_customer_push_runtime('https://qvkucvcjmojjbphlzlks.supabase.co','com.barberplusplus.customer.test',array['sandbox']);
select set_config('apns.device',jsonb_build_object('deviceId','fa280000-0000-4000-8000-000000000001','deviceSecret',repeat('b',64),'version',1,'token',repeat('ac',32),'environment','production','language','en','permission',false)::text,true);
set local role service_role;
select throws_ok($$select public.customer_push_api('push-register',current_setting('apns.device')::jsonb)$$,'P0001','INVALID_REQUEST','Test rejects production device registration');
reset role;
select set_config('apns.key',jsonb_build_object('privateKey',E'-----BEGIN PRIVATE KEY-----\nZmFrZQ==\n-----END PRIVATE KEY-----','keyId','SANDBOX001','teamId','TESTTEAM01')::text,true);
select throws_ok($$select public.configure_customer_push_credential('production',current_setting('apns.key')::jsonb)$$,'P0001','PUSH_ENVIRONMENT_NOT_ALLOWED','Test cannot import production key');
select throws_ok($$select public.configure_customer_push_runtime('https://qvkucvcjmojjbphlzlks.supabase.co','com.barberplusplus.customer.test',array['sandbox','production'])$$,'23514',null,'Test cannot allow production tokens');
select public.configure_customer_push(current_setting('apns.key')::jsonb||'{"enabled":false}',repeat('a',64));
select set_config('apns.legacy',md5((select decrypted_secret from vault.decrypted_secrets where name='customer_push_apns')),true);
select set_config('apns.dispatch',md5((select decrypted_secret from vault.decrypted_secrets where name='customer_push_dispatch_secret')),true);
select set_config('apns.runtime',(select row_to_json(r)::text from private.customer_push_runtime r where singleton),true);
select throws_ok($$select public.configure_customer_push_credential(null,current_setting('apns.key')::jsonb)$$,'P0001','PUSH_ENVIRONMENT_NOT_ALLOWED','null environment denied');
select throws_ok($$select public.configure_customer_push_credential('unknown',current_setting('apns.key')::jsonb)$$,'P0001','PUSH_ENVIRONMENT_NOT_ALLOWED','unknown environment denied');
select throws_ok($$select public.configure_customer_push_credential('sandbox',null)$$,'P0001','INVALID_REQUEST','null config denied');
select throws_ok($$select public.configure_customer_push_credential('sandbox','[]')$$,'P0001','INVALID_REQUEST','array config denied');
select throws_ok($$select public.configure_customer_push_credential('sandbox',current_setting('apns.key')::jsonb-'teamId')$$,'P0001','INVALID_REQUEST','missing key denied');
select throws_ok($$select public.configure_customer_push_credential('sandbox',current_setting('apns.key')::jsonb||'{"environment":"production"}')$$,'P0001','INVALID_REQUEST','client scope override denied');
select throws_ok($$select public.configure_customer_push_credential('sandbox',current_setting('apns.key')::jsonb||'{"privateKey":17}')$$,'P0001','INVALID_REQUEST','non-string PEM denied');
select throws_ok($$select public.configure_customer_push_credential('sandbox',current_setting('apns.key')::jsonb||'{"privateKey":"bad"}')$$,'P0001','INVALID_REQUEST','malformed PEM denied');
select throws_ok($$select public.configure_customer_push_credential('sandbox',current_setting('apns.key')::jsonb||jsonb_build_object('privateKey',repeat('a',17000)))$$,'P0001','INVALID_REQUEST','oversized PEM denied');
select throws_ok($$select public.configure_customer_push_credential('sandbox',current_setting('apns.key')::jsonb||'{"keyId":"short"}')$$,'P0001','INVALID_REQUEST','invalid key ID denied');
select throws_ok($$select public.configure_customer_push_credential('sandbox',current_setting('apns.key')::jsonb||'{"teamId":"short"}')$$,'P0001','INVALID_REQUEST','invalid team ID denied');
select throws_ok($$select public.configure_customer_push_credential('sandbox',current_setting('apns.key')::jsonb||'{"teamId":"OTHERTEAM1"}')$$,'P0001','PUSH_CREDENTIAL_TEAM_MISMATCH','different team denied');
set local role service_role;
select is(public.configure_customer_push_credential('sandbox',current_setting('apns.key')::jsonb),true,'service imports synthetic sandbox slot');
reset role;
select is(public.customer_push_configuration()->'credentials'->'sandbox'->>'environment','sandbox','server binds environment');
select is(public.customer_push_configuration()->'credentials'->'sandbox'->>'topic','com.barberplusplus.customer.test','server binds topic');
select is(public.customer_push_configuration()->'credentials'->'sandbox'->>'apiUrl','https://qvkucvcjmojjbphlzlks.supabase.co','server binds API');
select is(public.customer_push_configuration()->>'enabled','false','import cannot enable delivery');
select is(md5((select decrypted_secret from vault.decrypted_secrets where name='customer_push_apns')),current_setting('apns.legacy'),'legacy key unchanged');
select is(md5((select decrypted_secret from vault.decrypted_secrets where name='customer_push_dispatch_secret')),current_setting('apns.dispatch'),'dispatcher secret unchanged');
select is((select row_to_json(r)::text from private.customer_push_runtime r where singleton),current_setting('apns.runtime'),'runtime unchanged');
-- Simulate live runtime inside this transaction only; no real key or external requests.
select public.configure_customer_push_runtime('https://srv1073968.hstgr.cloud','com.barberplusplus.customer',array['sandbox','production']);
set local role service_role;
select is(public.customer_push_api('push-register',current_setting('apns.device')::jsonb)->>'success','true','simulated live runtime accepts production registration');
select is(public.customer_push_api('push-register',current_setting('apns.device')::jsonb||'{"deviceId":"fa280000-0000-4000-8000-000000000002","environment":"sandbox"}')->>'success','true','simulated live runtime retains USB sandbox registration');
reset role;
select is((select count(*) from private.customer_push_devices where id in('fa280000-0000-4000-8000-000000000001','fa280000-0000-4000-8000-000000000002') and token=repeat('ac',32)),2::bigint,'same synthetic token stays isolated by environment');
select is((select count(*) from private.customer_push_devices where id in('fa280000-0000-4000-8000-000000000001','fa280000-0000-4000-8000-000000000002') and topic='com.barberplusplus.customer' and not permission),2::bigint,'both test devices have live topic and delivery permission disabled');
select throws_ok($$select public.configure_customer_push_credential('production',current_setting('apns.key')::jsonb)$$,'P0001','PUSH_CREDENTIAL_ENVIRONMENT_MISMATCH','production cannot reuse sandbox key');
select is(public.configure_customer_push_credential('production',current_setting('apns.key')::jsonb||'{"keyId":"PRODKEY001"}'),true,'distinct synthetic production key imports');
select is(public.customer_push_configuration()->'credentials'->'production'->>'topic','com.barberplusplus.customer','production key binds live topic');
select is(public.customer_push_configuration()->'credentials'->'production'->>'apiUrl','https://srv1073968.hstgr.cloud','production key binds live API');
select is(public.customer_push_configuration()->'credentials'->'production'->>'environment','production','production key binds environment');
select throws_ok($$select public.configure_customer_push_credential('sandbox',current_setting('apns.key')::jsonb||'{"keyId":"PRODKEY001"}')$$,'P0001','PUSH_CREDENTIAL_ENVIRONMENT_MISMATCH','sandbox cannot reuse production key');
select is(public.configure_customer_push_credential('production',current_setting('apns.key')::jsonb||'{"keyId":"PRODKEY002"}'),true,'production key rotates independently');
select is(public.customer_push_configuration()->'credentials'->'sandbox'->>'keyId','SANDBOX001','production rotation preserves sandbox slot');
select is(public.customer_push_configuration()->>'keyId','SANDBOX001','production rotation preserves legacy key');
select is(public.customer_push_configuration()->>'enabled','false','production rotation preserves disabled flag');
select is(public.customer_push_configuration()->>'dispatchSecret',repeat('a',64),'production rotation preserves dispatch secret');
select * from finish();
rollback;
